"""Original Solar Array Strider anatomy and independently guided actions."""
import json
from pathlib import Path
SOURCE=Path(__file__).resolve().parent
UNIT='unit_sunvault_solar_array_striders'
IDENTITY=('Locked orthographic camera, original richly painted fantasy strategy sprite on a perfectly flat vivid GREEN RGB(0,255,0) background. One ivory, gold and deep-blue mechanical quadruped strider. Exactly FOUR articulated metal legs: near front, far front, near rear, far rear. Each leg has fixed gold-and-ivory armor plates, blue circular joint bearings and one broad pointed triangular metal foot. Far limbs may be naturally occluded behind near limbs, but stay attached to their own chassis joints. The compact ivory chassis has gold sun engravings and short hanging blue cloth strips. On top is the original rigid inclined array of three blue triangular sail-like panels in gold frames, one large round blue lens in a gold ring, and the gold forward curved bracket carrying exactly three smaller round lenses. Preserve all original rigid equipment, plates, leg lengths, lens sizes, panel count and gold braces. No human rider or humanoid arms. The entire machine faces three-quarter image right, remains the same anatomical size, and stays fully visible. The camera, lighting and flat empty green backdrop stay fixed. The blue lenses remain solid painted glass. Only the original machine and its cloth are visible. ')
ACTIONS={
 'move':([2,3,4],0,[[34,1],[68,2]],'Walk in place through coherent reciprocal quadruped strides. Lift, swing forward and plant the four separate feet in staggered near/far phases. Each knee bearing rotates physically and the matching upper leg carries weight. The chassis remains centered for game travel; the rigid array stays attached above it, with only small suspension movement. Cloth follows the gait. Finish in the original starting contact phase.'),
 'death':([14,11,12,13],3,[[34,1],[76,2]],'One gradual mechanical collapse. First both front knee joints lose support and fold, lowering the nose toward the ground; then the rear joints bend as the chassis descends. Keep each leg attached and fold its solid armor at the circular joints. The large array lowers with the chassis and its hinge, keeping all three panels and four lenses intact. End with the entire machine resting flattened on its folded legs in the supplied final grounded wreck; lenses dim, cloth rests on the floor. Hold still at the end.'),
 'attack':([14,6,7],0,[[30,1],[58,2]],'One physical forward chassis ram. The four feet brace, the rear knees compress to draw the body slightly back, then extend to push the plated front chassis toward image RIGHT. The front legs absorb the lunge and the entire solid lens array tilts forward on its mount. The machine retracts smoothly and regains its original upright ready stance. Every lens and panel remains attached and solid, the gold frame stays rigid. This is a physical shove by the chassis; only mechanical joints and cloth move.'),
 'defend':([14,9],1,[],'Lower into a stable defensive crouch. Spread the four feet modestly, fold the knee joints and lower the ivory chassis between them. Angle the same rigid lens array forward protectively. Keep the three panels, large lens and three small lenses fixed on their original supports. Finish and remain braced low with feet planted.'),
 'hit':([14,8],0,[[40,1]],'One brief external physical jolt makes the machine flex its front knees and dip the chassis. Its rear legs catch the weight; the lens assembly rocks on its mounting hinge while all rigid parts retain their shape. The four legs extend smoothly to restore balance and return to the original ready stance. Keep all equipment attached and in place.'),
 'cast':([14],0,[],'One deliberate physical acknowledgment and support gesture. With all four feet planted, the upper lens array slowly inclines forward on its chassis hinge, the forward lens bracket follows it, and the three blue panels tilt together as one rigid assembly. Pause in a clear forward bow, then rotate the same assembly smoothly back to its original upright angle. The legs flex only slightly to balance this movement; this is a mechanical bow, with the same solid painted glass and unchanged machinery throughout.')}
def pose(index):
 x,y=index%4*512,index//4*256
 return dict(source=f'art/animation/runtime/poses/{UNIT}.png',rects=[[x,y,x+512,y+256]],anchor=[x+256,y+248],scale=1,alpha_noise_cutoff=8)
if __name__=='__main__':
 for n,(clip,(refs,last,guides,action)) in enumerate(ACTIONS.items()):
  out=SOURCE/f'{clip}_v1';out.mkdir(exist_ok=True);assert not (out/'submission.json').exists()
  c=dict(unit_id=UNIT,clip=clip,scale=.8,anchor=[480,480],key_rgb=[0,255,0],protected_foreground_chroma=22,references=[pose(i) for i in refs],last=last,guides=guides,seed=926201+n,tiled_decode=dict(tile_size=256,overlap=64,temporal_size=16,temporal_overlap=4),prompt=IDENTITY+action)
  (out/'config.json').write_text(json.dumps(c,indent=2)+'\n',encoding='utf-8')
 (SOURCE/'delivery.json').write_text(json.dumps(dict(takes=[],visual_review=dict(status='pending',notes='Original four-leg machinery, lens-array articulation and native scale require review. Preserve original eight-pose idle only after review.')),indent=2)+'\n',encoding='utf-8')
